"""Bounded system views; errors remain distinct from empty healthy results."""
PROCESSES_PS=r'''$logical=[Environment]::ProcessorCount;$names=@{};Get-Process -ErrorAction SilentlyContinue|ForEach-Object{$names[$_.Id]=$_.ProcessName};@(Get-CimInstance Win32_PerfFormattedData_PerfProc_Process -OperationTimeoutSec 5 -ErrorAction Stop|Where-Object {$_.IDProcess -gt 0 -and $_.Name -notin @('Idle','_Total')}|Sort-Object PercentProcessorTime -Descending|Select-Object -First 300|ForEach-Object{@{id=[int]$_.IDProcess;name=if($names.ContainsKey([int]$_.IDProcess)){$names[[int]$_.IDProcess]}else{$_.Name};cpu_percent=[Math]::Round([double]$_.PercentProcessorTime/$logical,1);private_mb=[Math]::Round([double]$_.WorkingSetPrivate/1MB,1);io_read_bps=[double]$_.IOReadBytesPersec;io_write_bps=[double]$_.IOWriteBytesPersec;threads=$_.ThreadCount;handles=$_.HandleCount}})|ConvertTo-Json -Depth 4 -Compress'''
CONNECTIONS_PS=r'''$names=@{};Get-Process -ErrorAction SilentlyContinue|ForEach-Object{$names[$_.Id]=$_.ProcessName};$tcp=@(Get-NetTCPConnection -ErrorAction Stop|Select-Object -First 256|ForEach-Object{@{protocol='TCP';local=$_.LocalAddress;local_port=$_.LocalPort;remote=$_.RemoteAddress;remote_port=$_.RemotePort;state=[string]$_.State;pid=$_.OwningProcess;process=$names[[int]$_.OwningProcess]}});$udp=@(Get-NetUDPEndpoint -ErrorAction SilentlyContinue|Select-Object -First 128|ForEach-Object{@{protocol='UDP';local=$_.LocalAddress;local_port=$_.LocalPort;pid=$_.OwningProcess;process=$names[[int]$_.OwningProcess]}});@{tcp=$tcp;udp=$udp;bounded=$true}|ConvertTo-Json -Depth 5 -Compress'''
NETWORK_PS=r'''$rows=@(Get-NetIPConfiguration -ErrorAction Stop|ForEach-Object{@{name=$_.InterfaceAlias;index=$_.InterfaceIndex;ipv4=@($_.IPv4Address.IPAddress);gateway=@($_.IPv4DefaultGateway.NextHop);dns=@($_.DNSServer.ServerAddresses);status=[string]$_.NetAdapter.Status;link_speed=[string]$_.NetAdapter.LinkSpeed}});$dns=@();$error='';$ip=$null;$literal=[Net.IPAddress]::TryParse($p.host,[ref]$ip);$watch=[Diagnostics.Stopwatch]::StartNew();try{if($literal){$dns=@($ip.ToString())}else{$query=[Net.Dns]::GetHostAddressesAsync([string]$p.host);if(!$query.Wait(5000)){throw 'DNS не ответил за 5 секунд'};$dns=@($query.Result|Select-Object -First 8|ForEach-Object {$_.ToString()})}}catch{$error=$_.Exception.Message};@{adapters=$rows;addresses=$dns;dns_error=$error;ip_literal=$literal;dns_ms=[Math]::Round($watch.Elapsed.TotalMilliseconds,1)}|ConvertTo-Json -Depth 6 -Compress'''
BATTERY_PS=r'''$full=@(Get-CimInstance -Namespace root/WMI -ClassName BatteryFullChargedCapacity -OperationTimeoutSec 4 -ErrorAction Stop|ForEach-Object{@{instance=$_.InstanceName;full_mwh=[double]$_.FullChargedCapacity}});$design=@(Get-CimInstance -Namespace root/WMI -ClassName BatteryStaticData -OperationTimeoutSec 4 -ErrorAction Stop|ForEach-Object{@{instance=$_.InstanceName;designed_mwh=[double]$_.DesignedCapacity}});$cycles=@();try{$cycles=@(Get-CimInstance -Namespace root/WMI -ClassName BatteryCycleCount -OperationTimeoutSec 3 -ErrorAction Stop|ForEach-Object{@{instance=$_.InstanceName;cycles=$_.CycleCount}})}catch{};@{full=$full;designed=$design;cycles=$cycles}|ConvertTo-Json -Depth 5 -Compress'''
SECURITY_PS=r'''$m=Get-MpComputerStatus -ErrorAction Stop;@{antivirus_enabled=$m.AntivirusEnabled;realtime_enabled=$m.RealTimeProtectionEnabled;signatures_updated=$m.AntivirusSignatureLastUpdated.ToString('o');tamper_protected=$m.IsTamperProtected;quick_scan_end=if($m.QuickScanEndTime){$m.QuickScanEndTime.ToString('o')}else{$null};source='Microsoft Defender'}|ConvertTo-Json -Depth 4 -Compress'''
DISKS_PS=r'''@(Get-Disk -ErrorAction Stop|Where-Object {$_.Number -ge 0 -and $_.Number -le 255}|Select-Object -First 32|ForEach-Object{@{number=[int]$_.Number;name=$_.FriendlyName;bytes=[double]$_.Size;bus=[string]$_.BusType;health=[string]$_.HealthStatus;operational=[string]$_.OperationalStatus}})|ConvertTo-Json -Depth 4 -Compress'''
PERIPHERALS_PS=r'''@(Get-PnpDevice -PresentOnly -ErrorAction Stop|Where-Object {$_.Class -in @('USB','Bluetooth','Camera','Image','Printer','PrintQueue','HIDClass','Keyboard','Mouse')}|Select-Object -First 160|ForEach-Object{@{name=$_.FriendlyName;class=$_.Class;status=$_.Status;instance=$_.InstanceId}})|ConvertTo-Json -Depth 4 -Compress'''
PRINTERS_PS=r'''@(Get-Printer -ErrorAction Stop|Select-Object -First 32|ForEach-Object{$printer=$_;$jobs=@();try{$jobs=@(Get-PrintJob -PrinterName $printer.Name -ErrorAction Stop|Select-Object -First 50|ForEach-Object{@{id=$_.ID;status=[string]$_.JobStatus;pages=$_.TotalPages}})}catch{};@{name=$printer.Name;status=[string]$printer.PrinterStatus;driver=$printer.DriverName;jobs=$jobs}})|ConvertTo-Json -Depth 5 -Compress'''
STARTUP_EXTRA_PS=r'''$tasks=@(Get-ScheduledTask -ErrorAction Stop|Where-Object {$_.TaskPath -notlike '\Microsoft\*' -and ($_.Triggers|Where-Object {$_.CimClass.CimClassName -in @('MSFT_TaskLogonTrigger','MSFT_TaskBootTrigger')})}|Select-Object -First 150|ForEach-Object{@{name=$_.TaskName;path=$_.TaskPath;enabled=($_.State -ne 'Disabled');source='Планировщик';principal=$_.Principal.UserId;execute=@($_.Actions|ForEach-Object {$_.Execute})}});$services=@(Get-CimInstance Win32_Service -Filter "StartMode='Auto'" -OperationTimeoutSec 5 -ErrorAction Stop|Select-Object -First 250|ForEach-Object{@{name=$_.Name;display=$_.DisplayName;state=$_.State;path=$_.PathName;account=$_.StartName;source='Служба';readonly=$true}});@{tasks=$tasks;services=$services}|ConvertTo-Json -Depth 6 -Compress'''

LATENCY_PS=r'''$ping=New-Object System.Net.NetworkInformation.Ping;$reply=@();try{for($i=0;$i -lt 8;$i++){try{$r=$ping.Send($p.host,700);$reply+=@{ok=($r.Status -eq 'Success');milliseconds=if($r.Status -eq 'Success'){[int]$r.RoundtripTime}else{$null};status=[string]$r.Status;address=if($r.Address){[string]$r.Address}else{$null}}}catch{$reply+=@{ok=$false;milliseconds=$null;status='Недоступно'}};Start-Sleep -Milliseconds 100}}finally{$ping.Dispose()};@{host=$p.host;samples=$reply}|ConvertTo-Json -Depth 4 -Compress'''
CRASHES_PS=r'''$notes=@();$events=@();$filters=@(@{LogName='System';ProviderName='Microsoft-Windows-WHEA-Logger';StartTime=(Get-Date).AddDays(-14)},@{LogName='System';Id=@(41,6008,1001);StartTime=(Get-Date).AddDays(-14)},@{LogName='System';ProviderName='Microsoft-Windows-WindowsUpdateClient';Id=@(19,20);StartTime=(Get-Date).AddDays(-14)},@{LogName='Application';Id=@(1000,1001,1002);StartTime=(Get-Date).AddDays(-14)});foreach($f in $filters){try{$events+=@(Get-WinEvent -FilterHashtable $f -MaxEvents 30 -ErrorAction Stop|ForEach-Object{$m=[string]$_.Message;if($m.Length -gt 2000){$m=$m.Substring(0,2000)};@{id=$_.Id;source=$_.ProviderName;time=$_.TimeCreated.ToUniversalTime().ToString('o');message=$m;record=[string]$_.RecordId;kind=if($_.ProviderName -like '*WHEA*'){'whea'}elseif($_.ProviderName -like '*WindowsUpdate*'){'update'}elseif($_.Id -in @(41,6008)){'restart'}else{'crash'}}})}catch{if($_.FullyQualifiedErrorId -notlike 'NoMatchingEventsFound*'){$notes+='Часть журнала событий недоступна'}}};$dumps=@();$root=Join-Path $env:SystemRoot 'Minidump';try{$dumps=@(Get-ChildItem -LiteralPath $root -Filter '*.dmp' -File -ErrorAction Stop|Sort-Object LastWriteTimeUtc -Descending|Select-Object -First 20|ForEach-Object{@{name=$_.Name;bytes=[double]$_.Length;time=$_.LastWriteTimeUtc.ToString('o')}})}catch{if(Test-Path -LiteralPath $root){$notes+='Нет доступа к списку минидампов'}};@{events=@($events|Sort-Object time -Descending|Select-Object -First 80);dumps=$dumps;notes=@($notes|Select-Object -Unique)}|ConvertTo-Json -Depth 6 -Compress'''
